@@ -1,2 +1,16 @@
 # PatchBook
-Implement SPEC.md and add a short usage example.
+
+An in-memory JSON document with atomic edits and replayable receipts.
+
+```js
+import { createPatchBook } from './src/patchbook.js';
+
+const book = createPatchBook({ items: ['a', 'b', 'c', 'd'] });
+const receipt = book.apply({
+  id: 'move-b',
+  baseRevision: 0,
+  ops: [{ op: 'move', from: '/items/1', path: '/items/3' }]
+});
+
+console.log(receipt.document); // { items: ['a', 'c', 'd', 'b'] }
+```
