index 3066584..a66b3c6 100644
--- a/src/patchbook.js
+++ b/src/patchbook.js
@@ -1,2 +1,181 @@
-export function createPatchBook(){throw new Error('Not implemented');}
-export function restorePatchBook(){throw new Error('Not implemented');}
+const invalid = (code, message) => Object.assign(new Error(message), { code });
+const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
+const plain = value => value !== null && typeof value === 'object' &&
+  (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
+
+function cloneJson(value, stack = new Set()) {
+  if (value === null || typeof value === 'string' || typeof value === 'boolean') return value;
+  if (typeof value === 'number' && Number.isFinite(value)) return value;
+  if (typeof value !== 'object' || stack.has(value)) throw invalid('INVALID', 'Expected a JSON value');
+  stack.add(value);
+  let copy;
+  if (Array.isArray(value)) {
+    copy = new Array(value.length);
+    for (let i = 0; i < value.length; i++) {
+      if (!own(value, i)) throw invalid('INVALID', 'Sparse arrays are not JSON values');
+      copy[i] = cloneJson(value[i], stack);
+    }
+  } else {
+    if (!plain(value)) throw invalid('INVALID', 'Expected a plain object');
+    copy = Object.getPrototypeOf(value) === null ? Object.create(null) : {};
+    for (const key of Object.keys(value)) Object.defineProperty(copy, key, {
+      value: cloneJson(value[key], stack), enumerable: true, writable: true, configurable: true
+    });
+  }
+  stack.delete(value);
+  return copy;
+}
+
+function equal(a, b) {
+  if (typeof a !== typeof b || a === null || b === null) return a === b;
+  if (typeof a === 'number') return a === b; // Includes equality of -0 and 0.
+  if (typeof a !== 'object') return a === b;
+  if (Array.isArray(a) || Array.isArray(b))
+    return Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((v, i) => equal(v, b[i]));
+  const ak = Object.keys(a), bk = Object.keys(b);
+  return ak.length === bk.length && ak.every(k => own(b, k) && equal(a[k], b[k]));
+}
+
+function parsePath(path) {
+  if (path === '') return [];
+  if (!path.startsWith('/')) throw invalid('PATH_SYNTAX', 'Path must begin with /');
+  return path.slice(1).split('/').map(segment => {
+    let decoded = '';
+    for (let i = 0; i < segment.length; i++) {
+      if (segment[i] !== '~') decoded += segment[i];
+      else {
+        const next = segment[++i];
+        if (next === '0') decoded += '~';
+        else if (next === '1') decoded += '/';
+        else throw invalid('PATH_SYNTAX', 'Invalid path escape');
+      }
+    }
+    return decoded;
+  });
+}
+
+function validateRequest(request) {
+  if (!plain(request)) throw invalid('INVALID', 'Request must be a plain object');
+  const keys = Object.keys(request);
+  if (keys.length !== 3 || !['id', 'baseRevision', 'ops'].every(k => own(request, k)))
+    throw invalid('INVALID', 'Request must contain exactly id, baseRevision and ops');
+  const { id, baseRevision, ops } = request;
+  if (typeof id !== 'string' || id.length < 1 || id.length > 64 ||
+      !Number.isSafeInteger(baseRevision) || baseRevision < 0 || !Array.isArray(ops) ||
+      ops.length < 1 || ops.length > 32) throw invalid('INVALID', 'Invalid request fields');
+  const parsed = [];
+  for (let i = 0; i < ops.length; i++) {
+    if (!own(ops, i) || !plain(ops[i])) throw invalid('INVALID', 'Invalid operation');
+    const op = ops[i], kind = op.op;
+    const fields = kind === 'put' || kind === 'check' ? ['op', 'path', 'value'] :
+      kind === 'remove' ? ['op', 'path'] : kind === 'move' ? ['op', 'from', 'path'] : null;
+    if (!fields || Object.keys(op).length !== fields.length || !fields.every(k => own(op, k)))
+      throw invalid('INVALID', 'Invalid operation shape');
+    if (typeof op.path !== 'string' || (kind === 'move' && typeof op.from !== 'string'))
+      throw invalid('INVALID', 'Path must be a string');
+    const path = parsePath(op.path), from = kind === 'move' ? parsePath(op.from) : null;
+    const value = kind === 'put' || kind === 'check' ? cloneJson(op.value) : undefined;
+    parsed.push({ kind, path, from, value });
+  }
+  // Copy the original ops separately: replay compares the submitted request, not an execution-mutated value.
+  return { id, baseRevision, ops: cloneJson(ops), parsed };
+}
+
+function lookup(root, segments) {
+  let value = root;
+  for (const segment of segments) {
+    if (Array.isArray(value)) {
+      const index = arrayIndex(segment);
+      if (index >= value.length) throw invalid('INDEX', 'Array index out of range');
+      value = value[index];
+    } else if (value !== null && typeof value === 'object') {
+      if (!own(value, segment)) throw invalid('NOT_FOUND', 'Object key not found');
+      value = value[segment];
+    } else throw invalid('TYPE', 'Cannot traverse a primitive');
+  }
+  return value;
+}
+function arrayIndex(segment) {
+  if (!/^(0|[1-9][0-9]*)$/.test(segment)) throw invalid('INDEX', 'Invalid array index');
+  const n = Number(segment);
+  if (!Number.isSafeInteger(n)) throw invalid('INDEX', 'Invalid array index');
+  return n;
+}
+function parentAt(root, segments, destination = false) {
+  const parent = lookup(root, segments.slice(0, -1)), key = segments.at(-1);
+  if (Array.isArray(parent)) {
+    if (destination && key === '-') return { parent, key: parent.length };
+    const index = arrayIndex(key);
+    if (index > parent.length || (!destination && index === parent.length))
+      throw invalid('INDEX', 'Array index out of range');
+    return { parent, key: index };
+  }
+  if (parent === null || typeof parent !== 'object') throw invalid('TYPE', 'Cannot traverse a primitive');
+  return { parent, key };
+}
+function put(root, path, value) {
+  if (path.length === 0) return cloneJson(value);
+  const { parent, key } = parentAt(root, path, true), copy = cloneJson(value);
+  if (Array.isArray(parent)) parent.splice(key, 0, copy);
+  else Object.defineProperty(parent, key, { value: copy, enumerable: true, writable: true, configurable: true });
+  return root;
+}
+function remove(root, path) {
+  if (path.length === 0) return null;
+  const { parent, key } = parentAt(root, path);
+  if (Array.isArray(parent)) return (parent.splice(key, 1), root);
+  if (!own(parent, key)) throw invalid('NOT_FOUND', 'Object key not found');
+  delete parent[key];
+  return root;
+}
+function samePath(a, b) { return a.length === b.length && a.every((v, i) => v === b[i]); }
+function execute(root, op) {
+  if (op.kind === 'put') return put(root, op.path, op.value);
+  if (op.kind === 'remove') return remove(root, op.path);
+  if (op.kind === 'check') {
+    if (!equal(lookup(root, op.path), op.value)) throw invalid('TEST_FAILED', 'Check failed');
+    return root;
+  }
+  const value = cloneJson(lookup(root, op.from));
+  if (samePath(op.from, op.path)) return root;
+  if (op.path.length > op.from.length && op.from.every((v, i) => v === op.path[i]))
+    throw invalid('MOVE_INTO_SELF', 'Cannot move a value into itself');
+  root = remove(root, op.from);
+  return put(root, op.path, value);
+}
+
+function makeBook(document, revision, receipts) {
+  return {
+    read() { return { revision, document: cloneJson(document) }; },
+    apply(request) {
+      const validated = validateRequest(request);
+      const previous = receipts.find(entry => entry.id === validated.id);
+      if (previous) {
+        if (previous.baseRevision !== validated.baseRevision || !equal(previous.ops, validated.ops))
+          throw invalid('ID_CONFLICT', 'ID already committed with different content');
+        return cloneJson(previous.result);
+      }
+      if (validated.baseRevision !== revision) throw invalid('REVISION_CONFLICT', 'Revision mismatch');
+      let candidate = cloneJson(document);
+      for (const op of validated.parsed) candidate = execute(candidate, op);
+      revision++;
+      document = candidate;
+      const result = { id: validated.id, revision, document: cloneJson(document) };
+      receipts.push({ id: validated.id, baseRevision: validated.baseRevision, ops: validated.ops, result });
+      return cloneJson(result);
+    },
+    snapshot() {
+      return cloneJson({ schemaVersion: 1, revision, document, receipts });
+    }
+  };
+}
+
+export function createPatchBook(initial) {
+  return makeBook(cloneJson(initial), 0, []);
+}
+
+export function restorePatchBook(snapshot) {
+  if (snapshot === null || typeof snapshot !== 'object') throw invalid('INVALID', 'Snapshot must be an object');
+  const copy = cloneJson(snapshot);
+  return makeBook(copy.document, copy.revision, copy.receipts);
+}
diff --git a/tests/patchbook.test.js b/tests/patchbook.test.js
