+++ b/tests/patchbook.test.js
@@ -0,0 +1,171 @@
+import { test, expect } from 'vitest';
+import * as patchbook from '../src/patchbook.js';
+
+const { createPatchBook, restorePatchBook } = patchbook;
+const failureCode = (code, action) => {
+  try { action(); } catch (error) { expect(error.code).toBe(code); return; }
+  throw new Error(`Expected ${code}`);
+};
+const request = (id, baseRevision, ...ops) => ({ id, baseRevision, ops });
+
+test('[R-1] exports exactly the two public factories', () => {
+  expect(Object.keys(patchbook).sort()).toEqual(['createPatchBook', 'restorePatchBook']);
+  expect(typeof createPatchBook).toBe('function');
+  expect(typeof restorePatchBook).toBe('function');
+});
+
+test('[R-2] accepts JSON values and rejects non-JSON values', () => {
+  const value = { nil: null, yes: true, text: 'x', number: 2.5, list: [false, { n: 1 }] };
+  expect(createPatchBook(value).read().document).toEqual(value);
+  expect(createPatchBook(null).read().document).toBeNull();
+  for (const bad of [undefined, NaN, Infinity, [1, , 3]])
+    failureCode('INVALID', () => createPatchBook(bad));
+  const cycle = {}; cycle.self = cycle;
+  failureCode('INVALID', () => createPatchBook(cycle));
+  failureCode('INVALID', () => createPatchBook({ value: undefined }));
+});
+
+test('[R-3] clones initial input and detaches exact read results', () => {
+  const initial = { nested: { value: 1 } };
+  const book = createPatchBook(initial);
+  initial.nested.value = 2;
+  expect(book.read()).toEqual({ revision: 0, document: { nested: { value: 1 } } });
+  const read = book.read();
+  expect(Object.keys(read).sort()).toEqual(['document', 'revision']);
+  read.document.nested.value = 9;
+  expect(book.read().document.nested.value).toBe(1);
+});
+
+test('[R-4] validates outer request, scalar fields, operation shapes, values and paths', () => {
+  const book = createPatchBook({});
+  for (const invalid of [null, {}, { id: '', baseRevision: 0, ops: [{}] },
+    { id: 'x', baseRevision: -1, ops: [{ op: 'remove', path: '' }] },
+    { id: 'x', baseRevision: 0, ops: [] },
+    { id: 'x', baseRevision: 0, ops: [null] },
+    { id: 'x', baseRevision: 0, ops: [{ op: 'remove', path: '', extra: 1 }] },
+    { id: 'x', baseRevision: 0, ops: [{ op: 'put', path: '', value: NaN }] }])
+    failureCode('INVALID', () => book.apply(invalid));
+});
+
+test('[R-5] decodes path escapes once and safely handles literal special keys', () => {
+  const initial = Object.create(null);
+  initial['a/b'] = { '~': 1 };
+  initial['a~1b'] = { '~0': 0 };
+  initial.__proto__ = { value: 1 };
+  initial.constructor = 2;
+  initial.prototype = 3;
+  const book = createPatchBook(initial);
+  book.apply(request('escaped', 0, { op: 'put', path: '/a~1b/~0', value: 4 },
+    { op: 'put', path: '/__proto__/value', value: 8 },
+    { op: 'put', path: '/constructor', value: 5 },
+    { op: 'put', path: '/prototype', value: 6 },
+    { op: 'put', path: '/a~01b/~00', value: 7 }));
+  const result = book.read().document;
+  expect(result['a/b']['~']).toBe(4);
+  expect(result['a~1b']['~0']).toBe(7);
+  expect(result.__proto__.value).toBe(8);
+  expect(result.constructor).toBe(5);
+  expect(result.prototype).toBe(6);
+  for (const path of ['no-slash', '/bad~', '/bad~2'])
+    failureCode('PATH_SYNTAX', () => book.apply(request(`bad-${path}`, 1, { op: 'check', path, value: 0 })));
+});
+
+test('[R-6] uses own object keys and canonical array indices with destination append', () => {
+  const book = createPatchBook({ obj: { '-': 1, '01': 2 }, list: ['a'] });
+  book.apply(request('keys', 0, { op: 'check', path: '/obj/-', value: 1 },
+    { op: 'check', path: '/obj/01', value: 2 }, { op: 'put', path: '/list/-', value: 'b' }));
+  expect(book.read().document.list).toEqual(['a', 'b']);
+  failureCode('NOT_FOUND', () => book.apply(request('missing', 1, { op: 'check', path: '/obj/nope', value: 0 })));
+  failureCode('TYPE', () => book.apply(request('primitive', 1, { op: 'check', path: '/list/0/x', value: 0 })));
+  for (const path of ['/list/01', '/list/-', '/list/8', '/list/9007199254740992'])
+    failureCode('INDEX', () => book.apply(request(`index-${path}`, 1, { op: 'check', path, value: 0 })));
+});
+
+test('[R-7] applies root, object and array edits and JSON checks', () => {
+  const book = createPatchBook({ obj: { a: 1 }, list: ['a', 'c'] });
+  book.apply(request('edit', 0,
+    { op: 'put', path: '/obj/b', value: { x: -0 } },
+    { op: 'put', path: '/list/1', value: 'b' },
+    { op: 'check', path: '/obj/b', value: { x: 0 } },
+    { op: 'check', path: '/obj', value: { b: { x: 0 }, a: 1 } }));
+  expect(book.read().document.list).toEqual(['a', 'b', 'c']);
+  book.apply(request('remove', 1, { op: 'remove', path: '/obj/a' }));
+  book.apply(request('root-put', 2, { op: 'put', path: '', value: null }));
+  expect(book.read().document).toBeNull();
+  const root = createPatchBook({ a: 1 });
+  root.apply(request('root-remove', 0, { op: 'remove', path: '' }));
+  expect(root.read().document).toBeNull();
+  failureCode('TEST_FAILED', () => createPatchBook({ a: [1, 2] }).apply(request('unequal', 0,
+    { op: 'check', path: '/a', value: [2, 1] })));
+});
+
+test('[R-8] moves with decoded path rules and post-removal destinations', () => {
+  const book = createPatchBook({ items: ['a', 'b', 'c', 'd'], nested: { child: 1 } });
+  book.apply(request('shift', 0, { op: 'move', from: '/items/1', path: '/items/3' }));
+  expect(book.read().document.items).toEqual(['a', 'c', 'd', 'b']);
+  book.apply(request('same', 1, { op: 'move', from: '/nested/child', path: '/nested/child' }));
+  failureCode('MOVE_INTO_SELF', () => book.apply(request('self', 2,
+    { op: 'move', from: '/nested', path: '/nested/new' })));
+  book.apply(request('to-root', 2, { op: 'move', from: '/nested', path: '' }));
+  expect(book.read().document).toEqual({ child: 1 });
+});
+
+test('[R-9] validates before history, checks revision before paths, and commits atomically', () => {
+  const book = createPatchBook({ a: 1 });
+  failureCode('PATH_SYNTAX', () => book.apply(request('id', 99, { op: 'remove', path: 'bad' })));
+  failureCode('REVISION_CONFLICT', () => book.apply(request('id', 99, { op: 'remove', path: '/missing' })));
+  failureCode('TEST_FAILED', () => book.apply(request('failed', 0,
+    { op: 'put', path: '/b', value: 2 }, { op: 'check', path: '/a', value: 9 })));
+  expect(book.read()).toEqual({ revision: 0, document: { a: 1 } });
+  expect(book.snapshot().receipts).toEqual([]);
+  expect(book.apply(request('failed', 0, { op: 'put', path: '/b', value: 2 })).revision).toBe(1);
+  expect(book.apply(request('check', 1, { op: 'check', path: '/a', value: 1 })).revision).toBe(2);
+});
+
+test('[R-10] replays historical receipts by structural request identity', () => {
+  const book = createPatchBook({ a: 1 });
+  const first = book.apply(request('x', 0, { op: 'put', path: '/b', value: { left: 1, right: 2 } }));
+  book.apply(request('y', 1, { op: 'remove', path: '/a' }));
+  const reordered = request('x', 0, { value: { right: 2, left: 1 }, path: '/b', op: 'put' });
+  expect(book.apply(reordered)).toEqual(first);
+  expect(book.read()).toEqual({ revision: 2, document: { b: { left: 1, right: 2 } } });
+  failureCode('ID_CONFLICT', () => book.apply(request('x', 0, { op: 'put', path: '/b', value: 3 })));
+  failureCode('ID_CONFLICT', () => book.apply(request('x', 1, { op: 'put', path: '/b', value: { left: 1, right: 2 } })));
+  failureCode('PATH_SYNTAX', () => book.apply(request('x', 0, { op: 'put', path: '/bad~', value: 3 })));
+});
+
+test('[R-11] snapshots preserve exact historical data and restore independently', () => {
+  const book = createPatchBook({ a: 1 });
+  const old = book.apply(request('first', 0, { op: 'put', path: '/b', value: 2 }));
+  book.apply(request('second', 1, { op: 'remove', path: '/a' }));
+  const snapshot = book.snapshot();
+  expect(Object.keys(snapshot).sort()).toEqual(['document', 'receipts', 'revision', 'schemaVersion']);
+  expect(snapshot.receipts[0]).toEqual({ id: 'first', baseRevision: 0,
+    ops: [{ op: 'put', path: '/b', value: 2 }], result: old });
+  expect(Object.keys(snapshot.receipts[0].result).sort()).toEqual(['document', 'id', 'revision']);
+  failureCode('INVALID', () => restorePatchBook(null));
+  failureCode('INVALID', () => restorePatchBook(3));
+  const restored = restorePatchBook(JSON.parse(JSON.stringify(snapshot)));
+  expect(restored.apply(request('first', 0, { op: 'put', path: '/b', value: 2 }))).toEqual(old);
+  restored.apply(request('third', 2, { op: 'put', path: '/c', value: 3 }));
+  expect(book.read().document).toEqual({ b: 2 });
+  snapshot.document.b = 99;
+  expect(book.read().document.b).toBe(2);
+});
+
+test('[R-12] caller inputs and returned values cannot mutate book state or receipts', () => {
+  const initial = { nested: { value: 1 } };
+  const book = createPatchBook(initial);
+  const submitted = { id: 'put', baseRevision: 0,
+    ops: [{ op: 'put', path: '/nested', value: { value: 2 } }] };
+  const receipt = book.apply(submitted);
+  submitted.ops[0].value.value = 8;
+  receipt.document.nested.value = 9;
+  const read = book.read(); read.document.nested.value = 10;
+  const snapshot = book.snapshot(); snapshot.receipts[0].result.document.nested.value = 11;
+  expect(book.read().document.nested.value).toBe(2);
+  expect(book.apply({ ...submitted, ops: [{ op: 'put', path: '/nested', value: { value: 2 } }] })).toEqual(
+    { id: 'put', revision: 1, document: { nested: { value: 2 } } });
+  initial.nested.value = 12;
+  expect(book.read().document.nested.value).toBe(2);
+});
